//! `retime_range` — one range of the timeline played faster or slower on
//! every unlocked track, and everything after it moved up or back to stay
//! in step (road map "creator-jobs" CU9a, spec §11 CU-90). One op, so Clip ▸
//! Retime Range… is one undo step, "Retime Range".
//!
//! In order, each a part of CU-90:
//!
//! - (a) `from` and `to` are snapped and clamped to 0, and every time inside
//!   the range maps through `f(t) = snapped(from + round((t − from) ÷
//!   rate))`, `to′ = f(to)`. Both bounds are cut by `split_under_playhead`
//!   (`from`, then `to`), so a straddler splits exactly as `split` splits
//!   it. The PIECES are the clips on unlocked tracks wholly inside the
//!   range, found before the shift; everything at or after `to` moves by
//!   `to′ − to` through `edit_time.rs`'s `shift_clips`, which carries each
//!   moved clip's linked partner (AU-91). A piece starts at `f(s)` and lasts
//!   `f(e) − f(s)`, so pieces that touched still touch: a constant media
//!   piece plays at speed × rate, held to its media by
//!   `duration_resnapped`, its actions keeping their fraction; a ramped one
//!   is `scaled_profile`'s (SR-19); every other kind scales its start and
//!   duration (a graphic keeps its `length`, G-9). Markers inside map
//!   through `f`, markers at or after `to` move with the shift. Inside a
//!   nest the view has no markers and the merge writes none back, so none
//!   moves and none is checked.
//! - (b) Errors, then refusals, in CU-90's order; nothing changes when one
//!   fires. A rate of exactly 1 is an identity once the rate is known to be
//!   in range.
//! - The exit is `finish_placement` over the unlocked tracks.

use crate::edit_clip::clip_end;
use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::edit_link::linked_rate_sentence;
use crate::edit_speed_profile::profile_factors;
use crate::edit_time::{locked_track, shift_clips, unlocked_tracks};
use crate::model::{Clip, Project, Source};
use crate::outcome::Outcome;
use crate::speed_map::end_speed;
use crate::time::Ticks;

/// The range's time map: `from`, `to` and `to′` on the grid, and `rate`.
struct Retime {
    from: Ticks,
    to: Ticks,
    rate: f64,
    to_new: Ticks,
}

impl Retime {
    /// `f(t)` for a `t` inside `[from, to]`.
    fn map(&self, project: &Project, t: Ticks) -> Ticks {
        let scaled = ((t - self.from) as f64 / self.rate).round();
        project.snapped(self.from.saturating_add(scaled as Ticks))
    }

    /// Where a marker at `t` goes: through `f` inside the range, by the
    /// shift at or after `to`, nowhere before `from`.
    fn marker(&self, project: &Project, t: Ticks) -> Ticks {
        if t >= self.to {
            t.saturating_add(self.to_new - self.to)
        } else if t >= self.from {
            self.map(project, t)
        } else {
            t
        }
    }
}

impl Project {
    /// Plays `[from, to)` at `rate` on every unlocked track and moves what
    /// follows by the range's lost or gained length (spec §6, §11 CU-90).
    /// `keep_pitch`, when given, is set on every media piece's audio, as
    /// `set_speed` sets it.
    pub fn retime_range(
        &self,
        from: Ticks,
        to: Ticks,
        rate: f64,
        keep_pitch: Option<bool>,
    ) -> Result<Outcome, String> {
        if !(rate.is_finite() && rate > 0.0) {
            return Err(format!("rate must be a positive number, not {rate}"));
        }
        let from = self.snapped(from).max(0);
        let to = self.snapped(to).max(0);
        if to <= from {
            return Err(format!(
                "retime_range's to must be after its from (from {from}, to {to} ticks, on the \
                 frame grid)"
            ));
        }
        if !(SPEED_MIN..=SPEED_MAX).contains(&rate) {
            return Ok(Outcome::Refused(format!(
                "a range can be retimed by ×{SPEED_MIN} to ×{SPEED_MAX}, not ×{rate}"
            )));
        }
        if rate == 1.0 {
            return Ok(Outcome::Identity);
        }
        let mut retime = Retime {
            from,
            to,
            rate,
            to_new: to,
        };
        retime.to_new = retime.map(self, to);
        if let Some(why) = self.retime_refusal(&retime) {
            return Ok(Outcome::Refused(why));
        }

        let mut cut = match self.split_under_playhead(from)? {
            Outcome::Applied(split) => split,
            Outcome::Identity | Outcome::Refused(_) => self.clone(),
        };
        if let Outcome::Applied(split) = cut.split_under_playhead(to)? {
            cut = split;
        }
        let unlocked = unlocked_tracks(&cut);
        let pieces: Vec<Clip> = cut
            .clips
            .iter()
            .filter(|c| unlocked.contains(&c.track) && c.start >= from && clip_end(c) <= to)
            .cloned()
            .collect();
        for piece in &pieces {
            if let Some(why) = self.piece_refusal(&cut, piece, &retime) {
                return Ok(Outcome::Refused(why));
            }
        }

        let mut next = cut.clone();
        if let Some(why) = shift_clips(&mut next, to, retime.to_new - to) {
            return Ok(Outcome::Refused(why));
        }
        for piece in &pieces {
            let moved = next.retimed_piece(piece, &retime, keep_pitch);
            if let Some(slot) = next.clip_mut(piece.id) {
                *slot = moved;
            }
        }
        for marker in next.markers.iter_mut() {
            marker.time = retime.marker(self, marker.time);
        }
        let unlocked = unlocked_tracks(&next);
        self.finish_placement(next, &unlocked)
    }

    /// CU-90 (b)'s refusals (2)–(6), on the project as the caller sent it.
    fn retime_refusal(&self, retime: &Retime) -> Option<String> {
        let (from, to) = (retime.from, retime.to);
        if to - from < self.frame().saturating_mul(2) {
            return Some(format!(
                "the range from {from} to {to} ticks is shorter than two frames"
            ));
        }
        for track in self.tracks.iter().filter(|t| t.locked) {
            if self
                .clips
                .iter()
                .any(|c| c.track == track.id && clip_end(c) > from)
            {
                return Some(locked_track(
                    track.id,
                    "its clips after the range's start would fall out of step with the retimed \
                     range",
                ));
            }
        }
        let unlocked = unlocked_tracks(self);
        let inside = self
            .clips
            .iter()
            .filter(|c| unlocked.contains(&c.track) && c.start < to && clip_end(c) > from);
        for clip in inside {
            let c = clip.id;
            if matches!(clip.source, Source::Nest { .. }) {
                return Some(format!(
                    "clip {c} is a nest, which has no speed; move the range off it, or retime \
                     inside the nest"
                ));
            }
            if clip.text.as_ref().is_some_and(|t| !t.words.is_empty()) {
                return Some(format!(
                    "clip {c} is a caption page with timed words, which a retime cannot move; \
                     move the range off it"
                ));
            }
            if let Some(partner) = clip.linked {
                return Some(linked_rate_sentence(c, partner));
            }
        }
        for track in &unlocked {
            for overlap in self.overlaps_on_track(*track) {
                let end = overlap.start.saturating_add(overlap.duration);
                if overlap.start <= to && end >= from {
                    return Some(format!(
                        "clip {} has a transition from clip {} from {} to {end} ticks, which \
                         touches the range; move the range off it or remove the transition",
                        overlap.later, overlap.earlier, overlap.start
                    ));
                }
            }
        }
        let moved: Vec<Ticks> = self
            .markers
            .iter()
            .map(|m| retime.marker(self, m.time))
            .collect();
        for (j, time) in moved.iter().enumerate() {
            if let Some(i) = moved.iter().take(j).position(|t| t == time) {
                return Some(format!(
                    "markers {} and {} would both be at {time} ticks after a retime by ×{}, and \
                     two markers may not share a time; move one of them first",
                    self.markers[i].id, self.markers[j].id, retime.rate
                ));
            }
        }
        None
    }

    /// CU-90 (b)'s refusal (7) for one piece of `cut`: a rate past the
    /// speed limits, or a piece under one frame. The piece is named by its
    /// source clip — a piece `self` has not got is the second half of the
    /// clip that straddled `from` on its track.
    fn piece_refusal(&self, cut: &Project, piece: &Clip, retime: &Retime) -> Option<String> {
        let source = match self.clip(piece.id) {
            Some(clip) => clip.id,
            None => self
                .clips
                .iter()
                .find(|c| {
                    c.track == piece.track && c.start < retime.from && clip_end(c) > retime.from
                })
                .map_or(piece.id, |c| c.id),
        };
        let rate = retime.rate;
        if matches!(piece.source, Source::Media { .. }) {
            let past = match profile_factors(piece) {
                None => Some(piece.speed * rate),
                Some((low, high)) => {
                    let rates = std::iter::once(piece.speed)
                        .chain(piece.actions.iter().filter_map(end_speed));
                    if rate > high {
                        Some(rates.fold(f64::NEG_INFINITY, f64::max) * rate)
                    } else if rate < low {
                        Some(rates.fold(f64::INFINITY, f64::min) * rate)
                    } else {
                        None
                    }
                }
            };
            if let Some(r) = past.filter(|r| !(SPEED_MIN..=SPEED_MAX).contains(r)) {
                let (limit, which) = match r > SPEED_MAX {
                    true => (SPEED_MAX, "fastest"),
                    false => (SPEED_MIN, "slowest"),
                };
                return Some(format!(
                    "clip {source} would play at ×{r}, past ×{limit}, the {which} a clip can play"
                ));
            }
        }
        let length = retime.map(cut, clip_end(piece)) - retime.map(cut, piece.start);
        if length < cut.frame() {
            return Some(format!(
                "clip {source} would last under one frame at ×{rate}"
            ));
        }
        None
    }

    /// One piece retimed: started at `f(s)`, lasting `f(e) − f(s)` — a
    /// media piece at speed × rate (held to its media) or its ramp scaled
    /// (SR-19), every other kind scaled; actions keep their fraction.
    fn retimed_piece(&self, piece: &Clip, retime: &Retime, keep_pitch: Option<bool>) -> Clip {
        let start = retime.map(self, piece.start);
        let length = retime.map(self, clip_end(piece)) - start;
        let mut moved = piece.clone();
        moved.start = start;
        if !matches!(piece.source, Source::Media { .. }) {
            moved.duration = length;
            self.rescale_actions(&mut moved.actions, piece.duration, length);
            return moved;
        }
        if profile_factors(piece).is_some() {
            moved = self.scaled_profile(&moved, retime.rate, length);
        } else {
            moved.speed = piece.speed * retime.rate;
            moved.duration = length;
            moved.duration = self.duration_resnapped(&moved);
            self.rescale_actions(&mut moved.actions, piece.duration, moved.duration);
        }
        if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
            audio.keep_pitch = keep;
        }
        moved
    }
}

//! `add_speed_ramp`, the speed ramp presets (spec §11 SR-23, #340): a Ramp
//! Up, a Ramp Down, a Speed Dip or a Speed Burst made in ONE step out of
//! ordinary Speed actions — actions whose `end` names a `speed` (SR-1,
//! SR-10) — so undo, the band drags, the inspector and the plan read them
//! exactly as they read one made by hand.
//!
//! **Everything is CLIP time**, as `add_action`'s `at` is: `from` and `to`
//! are both given or both absent, which is the clip's whole length [0, D).
//! The BASE b is the rate the clip plays at `from` before the edit
//! (`rate_in_force`), which after an earlier speed action is that action's
//! end rate and not `clip.speed`.
//!
//! - **Ramp Up / Ramp Down** — one action [from, to) ending at `rate`: the
//!   clip ramps from b to it and holds it after.
//! - **Speed Dip / Speed Burst** — two actions of length r each, r being
//!   `(to − from)·(1 − hold)/2` snapped DOWN onto the grid and never under
//!   one frame: [from, from + r) ending at `rate`, and [to − r, to) ending
//!   at b. The span between them holds the target; at `hold` 0 they abut.
//!
//! "Up" and "down" are about the base rate, not about time: Up and Burst
//! need a rate above b, Down and Dip one below it. A ramp mirrored in TIME
//! would have to change the clip's own `speed`, and a preset makes only
//! Speed actions.
//!
//! **The lane's one rule holds** (spec §5.4): an action the span runs into
//! is a REFUSAL naming it, never replaced — a replacement would drop the
//! action's other keys — and the span tested is the WHOLE of [from, to)
//! for every shape, so an action sitting in a dip's hold gap is refused as
//! well: the gap must hold the target. **The clip keeps its slot** (SR-2):
//! a preset that would read past the media's end is refused naming the
//! largest rate that fits, through R1's solve (`largest_fitting_rate`).
//!
//! Errs come first, then the refusals, each in the order SR-23 lists them;
//! every sentence the lane already has is reused, not restated.

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::edit_action::{action_overlaps, action_past_end, overlapping_action};
use crate::edit_action_speed::read_speed_end;
use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::model::{Action, Clip, Curve, Project};
use crate::outcome::Outcome;
use crate::speed_map::rate_in_force;
use crate::time::Ticks;

/// The four presets (SR-23 (c)).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RampShape {
    RampUp,
    RampDown,
    SpeedDip,
    SpeedBurst,
}

/// A dip's or a burst's hold when `hold` is absent: half the span at the
/// target, a quarter each side ramping.
pub const HOLD_DEFAULT: f64 = 0.5;
/// The most of the span a hold may take. Below 1 so each ramp keeps some
/// length to ease over; one frame is its floor in any case.
pub const HOLD_MAX: f64 = 0.9;

impl RampShape {
    /// The shape as a refusal names it.
    fn name(self) -> &'static str {
        match self {
            RampShape::RampUp => "a ramp up",
            RampShape::RampDown => "a ramp down",
            RampShape::SpeedDip => "a speed dip",
            RampShape::SpeedBurst => "a speed burst",
        }
    }

    /// Whether the target must lie ABOVE the base rate (Up and Burst) or
    /// below it (Down and Dip).
    fn rises(self) -> bool {
        matches!(self, RampShape::RampUp | RampShape::SpeedBurst)
    }

    /// Whether the shape returns to the base rate: two actions and a hold.
    fn returns(self) -> bool {
        matches!(self, RampShape::SpeedDip | RampShape::SpeedBurst)
    }
}

/// One Speed action: a span ending at `rate`.
fn speed_action(id: u32, start: Ticks, duration: Ticks, curve: Curve, rate: f64) -> Action {
    Action {
        id,
        start,
        duration,
        curve,
        end: json!({ "speed": rate }),
    }
}

impl Project {
    /// The speed ramp presets (the module doc, spec §11 SR-23).
    #[allow(clippy::too_many_arguments)]
    pub fn add_speed_ramp(
        &self,
        clip: u32,
        shape: RampShape,
        rate: f64,
        from: Option<Ticks>,
        to: Option<Ticks>,
        curve: Option<Curve>,
        hold: Option<f64>,
    ) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        // Only a media clip has a window to read at a rate; the sentence is
        // the end-rate door's own (`edit_action_speed.rs`).
        read_speed_end(&target, &Value::from(1.0))?;
        if !(rate.is_finite() && rate > 0.0) {
            return Err(format!("rate must be a positive number, not {rate}"));
        }
        let rate = rate.clamp(SPEED_MIN, SPEED_MAX);
        let (from, to) = match (from, to) {
            (None, None) => (0, target.duration),
            (Some(given_from), Some(given_to)) => {
                let from = self.snapped(given_from);
                if from < 0 {
                    return Err(format!("from must not be negative, not {given_from}"));
                }
                (from, self.snapped(given_to))
            }
            _ => return Err("from and to are given together or not at all".to_string()),
        };
        if to <= from {
            return Err(format!("to must be after from, not {to} against {from}"));
        }
        if hold.is_some() && !shape.returns() {
            return Err("hold is for speed_dip and speed_burst only".to_string());
        }

        let length = to - from;
        if to > target.duration {
            return Ok(Outcome::Refused(action_past_end(
                clip,
                from,
                length,
                target.duration,
            )));
        }
        // ONE test over the whole span, whatever the shape (SR-23 (e)).
        if let Some(other) = overlapping_action(&target.actions, None, from, length) {
            return Ok(Outcome::Refused(action_overlaps(clip, other)));
        }
        let frame = self.frame();
        if shape.returns() && length < 2 * frame {
            return Ok(Outcome::Refused(format!(
                "{} needs a span of at least two frames ({} ticks); {from} to {to} ticks is \
                 {length}",
                shape.name(),
                2 * frame
            )));
        }
        let base = rate_in_force(&target, from);
        let wrong_way = if shape.rises() {
            rate <= base
        } else {
            rate >= base
        };
        if wrong_way {
            return Ok(Outcome::Refused(format!(
                "{} needs a rate {} ×{base}, the rate clip {clip} plays at {from} ticks into \
                 it; ×{rate} is not",
                shape.name(),
                if shape.rises() { "above" } else { "below" }
            )));
        }

        let mut next = self.clone();
        let first = next.allocate_id();
        let second = shape.returns().then(|| next.allocate_id());
        let curve = curve.unwrap_or(Curve::EaseInOut);
        // A NaN hold reads as the default; any other is clamped into range.
        let hold = match hold {
            Some(h) if !h.is_nan() => h.clamp(0.0, HOLD_MAX),
            _ => HOLD_DEFAULT,
        };
        let ramp = self
            .snapped_down(((length as f64) * (1.0 - hold) / 2.0) as Ticks)
            .max(frame);
        // The clip with the preset at target rate `x`: the one closure the
        // edit and the fit both build from, so they cannot disagree.
        let build = |x: f64| -> Clip {
            let mut out = target.clone();
            match second {
                None => out
                    .actions
                    .push(speed_action(first, from, length, curve, x)),
                Some(second) => {
                    out.actions.push(speed_action(first, from, ramp, curve, x));
                    out.actions
                        .push(speed_action(second, to - ramp, ramp, curve, base));
                }
            }
            out
        };
        let after = build(rate);
        // A linked clip's rate is refused (spec §11 AU-94).
        if let Some(why) = self.linked_rate_refusal(&target, &after) {
            return Ok(Outcome::Refused(why));
        }
        if let Some(over) = self.overrun(&after) {
            let floor_k = if shape.rises() {
                (base * 1000.0).floor() as i64 + 1
            } else {
                (SPEED_MIN * 1000.0).round() as i64
            };
            let head = format!(
                "{} to ×{rate} would read clip {clip} {over} ticks past the end of its media",
                shape.name()
            );
            return Ok(Outcome::Refused(
                match self.largest_fitting_rate(&build, rate, floor_k) {
                    Some(fit) => format!("{head}; the largest rate that fits is ×{fit}"),
                    None if shape.rises() => format!("{head}, and no rate above ×{base} fits"),
                    None => format!("{head}, and no rate down to ×0.1 fits"),
                },
            ));
        }
        if let Some(slot) = next.clip_mut(clip) {
            *slot = after;
        }
        self.finish(next)
    }
}
//! `set_action_end`'s `speed` arm (format version 27, spec §11 SR-10), and
//! the refusals every action op that can move a ramped clip's out point
//! answers (SR-2, the road map's C).
//!
//! `speed` is a number at the TOP of an action's `end`, beside the groups:
//! the rate the clip ramps to along the action's curve and holds after
//! (`speed_map.rs`). It is a door of its own, as `graphic` is
//! (`edit_action_graphic.rs`): not a property group, so `check_end_patch`
//! steps over it and this file reads it. A finite number is clamped to
//! ×0.1–×1000 as `set_speed` clamps; any other kind is an `Err`, and so is a
//! rate on a clip that is not a media clip, which has no window to read at
//! one; a `null` removes it, as it removes any key.
//!
//! **The clip keeps its slot** (SR-2): a ramp edit never moves `start` or
//! `duration`, it changes how much source the clip reads, `in + S(D)`. An
//! edit that would read past the media's end is REFUSED, naming what fits:
//! the largest end rate (R1) — S(D) is affine in one action's end rate, so
//! two readings solve it — or, when no rate down to ×0.1 fits, the latest
//! clip end at ×0.1 (R2); and for a retime, a removal or an end rate taken
//! away, the latest clip end (R3).

use serde_json::Value;

use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::export::describe;
use crate::model::{Clip, Project, Source};
use crate::speed_map::SpeedMap;
use crate::time::Ticks;

/// Reads a patch's `speed` for `clip`: `None` for a `null` (remove it), the
/// clamped rate for a number. `Err` for any other JSON kind, then for a
/// clip that is not a media clip.
pub(crate) fn read_speed_end(clip: &Clip, value: &Value) -> Result<Option<f64>, String> {
    if value.is_null() {
        return Ok(None);
    }
    let Some(rate) = value.as_f64() else {
        return Err(format!("speed must be a number, not {}", describe(value)));
    };
    if !matches!(clip.source, Source::Media { .. }) {
        return Err(format!(
            "clip {} is not a media clip, and only a media clip's action can end at a speed",
            clip.id
        ));
    }
    Ok(Some(rate.clamp(SPEED_MIN, SPEED_MAX)))
}

/// `clip` with action `action`'s end rate set to `rate`.
fn ending_at(clip: &Clip, action: u32, rate: f64) -> Clip {
    let mut out = clip.clone();
    if let Some(found) = out.actions.iter_mut().find(|a| a.id == action) {
        if let Value::Object(end) = &mut found.end {
            end.insert("speed".to_string(), Value::from(rate));
        }
    }
    out
}

/// The `{}` a refusal names a rate in, on the 0.001 grid it was found on.
fn thousandths(k: i64) -> f64 {
    k as f64 / 1000.0
}

impl Project {
    /// The latest clip END that fits: the clip's start plus S⁻¹ of what the
    /// file holds past `in`, snapped DOWN onto the grid, never before the
    /// start.
    fn latest_fitting_end(&self, clip: &Clip) -> Ticks {
        let Some((source_in, file)) = self.window_of(clip) else {
            return clip.start;
        };
        let remaining = file.saturating_sub(source_in).max(0) as f64;
        let fits = match SpeedMap::of(clip) {
            Some(map) => map.time_at(remaining),
            None if clip.speed.is_finite() && clip.speed > 0.0 => {
                let t = (remaining / clip.speed).floor();
                if t.is_finite() {
                    t as Ticks
                } else {
                    0
                }
            }
            None => remaining as Ticks,
        };
        self.snapped_down(clip.start.saturating_add(fits))
            .max(clip.start)
    }

    /// The largest end rate on the 0.001 grid, below `rate`, at which
    /// action `action` of `after` reads inside its file: R1's solve, then
    /// its step down. `None` when none down to ×0.1 does. Read by R1 and by
    /// a split's second half (spec §11 SR-18 (e)).
    pub(crate) fn largest_fitting_end_rate(
        &self,
        after: &Clip,
        action: u32,
        rate: f64,
    ) -> Option<f64> {
        let floor = (SPEED_MIN * 1000.0).round() as i64;
        self.largest_fitting_rate(&|x| ending_at(after, action, x), rate, floor)
    }

    /// The largest rate x on the 0.001 grid, below `rate` and at or above
    /// `floor_k` thousandths, at which the clip `at_rate(x)` reads inside
    /// its file: R1's solve, then its step down. `None` when none does.
    /// `at_rate` must make S(D) affine in x — one action's end rate
    /// (`largest_fitting_end_rate`), or a preset's target, which every
    /// piece it builds ramps to, holds or ramps from (`add_speed_ramp`,
    /// spec §11 SR-23 (g)).
    pub(crate) fn largest_fitting_rate(
        &self,
        at_rate: &dyn Fn(f64) -> Clip,
        rate: f64,
        floor_k: i64,
    ) -> Option<f64> {
        let probe = at_rate(rate);
        let (source_in, file) = self.window_of(&probe)?;
        let fits = |x: f64| self.overrun(&at_rate(x)).is_none();
        // S(D) = α + β·x in the rate x: read at two rates in range, solved
        // for the file's remainder.
        let read = |x: f64| SpeedMap::of(&at_rate(x)).map(|m| m.source_at(probe.duration));
        let solved = match (read(SPEED_MIN), read(1.0)) {
            (Some(low), Some(one)) => {
                let beta = (one - low) / (1.0 - SPEED_MIN);
                let alpha = low - SPEED_MIN * beta;
                let remaining = file.saturating_sub(source_in) as f64;
                (beta > 0.0).then(|| (remaining - alpha) / beta)
            }
            _ => None,
        };
        let x = solved.filter(|x| x.is_finite())?;
        // Floored to 0.001, never at or above the rate that overran, then
        // stepped down a thousandth until it fits. The millionth keeps a
        // solve that lands a hair under an exact thousandth (×4 read as
        // 3.9999999) on it; the step down catches the rest.
        let below = (rate * 1000.0).ceil() as i64 - 1;
        let mut k = ((x * 1000.0 + 1e-6).floor() as i64).min(below).max(floor_k);
        while k >= floor_k {
            if fits(thousandths(k)) {
                return Some(thousandths(k));
            }
            k -= 1;
        }
        None
    }

    /// R1 / R2: `after` is the clip with action `action` ending at `rate`
    /// (already clamped). `None` when it fits.
    pub(crate) fn end_rate_refusal(&self, after: &Clip, action: u32, rate: f64) -> Option<String> {
        let over = self.overrun(after)?;
        let clip = after.id;
        if let Some(fitting) = self.largest_fitting_end_rate(after, action, rate) {
            return Some(format!(
                "ending action {action} at ×{rate} would read clip {clip} {over} ticks past the \
                 end of its media; the largest end rate that fits is ×{fitting}"
            ));
        }
        let end = self.latest_fitting_end(&ending_at(after, action, SPEED_MIN));
        Some(format!(
            "ending action {action} at ×{rate} would read clip {clip} {over} ticks past the end \
             of its media, and no end rate down to ×0.1 fits; at ×0.1 the latest clip end that \
             fits is {end} ticks"
        ))
    }

    /// R3: `after` is the clip once `what` (`retiming action 7`, `removing
    /// action 7`, `removing action 7's end rate`) is done. `None` when it
    /// fits.
    pub(crate) fn overrun_refusal(&self, after: &Clip, what: &str) -> Option<String> {
        let over = self.overrun(after)?;
        let end = self.latest_fitting_end(after);
        Some(format!(
            "{what} would read clip {} {over} ticks past the end of its media; the latest clip \
             end that fits is {end} ticks",
            after.id
        ))
    }
}
//! `set_action_end`'s END patch door, moved whole out of `edit_action.rs`
//! (road map "creator-jobs" CO2a1's toll, a pure move): [`check_end_patch`],
//! the walk of an end patch's three groups; [`not_a_target`], the keys an
//! action may not animate; [`prune_removed`], a `null`'s removal from the
//! stored end; and `off` (spec §11 CI-14) — [`check_off`] reading its paths
//! and [`key_off`] writing each one's `null`. `edit_action.rs` composes them
//! in `set_action_end`; `END_PATCH` is also `edit_action_graphic.rs`'s.

use serde_json::{json, Map, Value};

use crate::actions::MAX_PATCH_DEPTH;
use crate::edit_action_graphic::GRAPHIC_NOT_KEYED_OFF;
use crate::model::{AudioProps, ShapeProps, TextProps, VideoProps};
use crate::patch::{check_group_patch, merge_group, unknown_key, Group};

/// Removes from `value` every key the incoming `patch` set to `null` —
/// `set_action_end`'s delete rule (spec §6). Only keys the patch mentions
/// are touched, so a `null` that was already in the end patch (animating a
/// shadow away, say) survives untouched. `shift_remove`, because under
/// `preserve_order` `Map::remove` swaps the last key into the hole.
pub(crate) fn prune_removed(value: &mut Value, patch: &Value, depth: u32) {
    let Value::Object(patched) = patch else {
        return;
    };
    let Value::Object(target) = value else {
        return;
    };
    if depth >= MAX_PATCH_DEPTH {
        return;
    }
    for (key, sub) in patched {
        if sub.is_null() {
            target.shift_remove(key);
        } else if let Some(slot) = target.get_mut(key) {
            prune_removed(slot, sub, depth + 1);
        }
    }
}

/// What a refusal calls this op's patch. It is not one group's — the paths
/// inside it carry the group's name (`video.filters[1].kind`) — so it
/// cannot be a `Group`'s own subject.
pub(crate) const END_PATCH: &str = "an action end patch";

/// The groups §5.4's end patch may name. `shape` is not among them, and its
/// absence is a refusal rather than an omission: `evaluate_clip` passes a
/// clip's shape through untouched, so the key would be stored, reported as
/// success and animate nothing.
const END_GROUPS: [Group; 3] = [Group::Video, Group::Audio, Group::Text];

/// Walks an end patch's keys, kinds and values the way every other patch
/// is walked (`patch.rs`'s `check_group_patch`), group by group, and
/// refuses by the dotted path.
///
/// What belongs to THIS door rather than to a property group, and is why
/// the walk is composed here rather than called:
///
/// - **Three groups and no fourth.** Spec §5.4's patch is a subset of
///   `video`, `audio` and `text`. `shape` is refused rather than kept,
///   because `evaluate_clip` passes a clip's shape through untouched: the
///   key would be stored, reported as success, and animate nothing.
/// - **A `null` is a REMOVAL at every depth**, not a clear. The walk sees
///   it (so `{"video": {"blurr": null}}` is still an unknown key) and the
///   typed read does not (so `{"video": {"crop": null}}` is "stop animating
///   the crop" rather than a required field being cleared) —
///   `check_group_patch` is where that split lives, and [`prune_removed`]
///   below applies the same rule to the STORED end state.
pub(crate) fn check_end_patch(patch: &Value) -> Result<(), String> {
    let Value::Object(groups) = patch else {
        return Ok(());
    };
    for (key, body) in groups {
        // `graphic` is `edit_action_graphic.rs`'s arm and `speed`
        // `edit_action_speed.rs`'s, each read after this walk.
        if key == "graphic" || key == "speed" {
            continue;
        }
        // The three groups, by their own names rather than by three string
        // literals: a group renamed in `patch.rs` cannot drift from the
        // door that lists it.
        let group = END_GROUPS
            .into_iter()
            .find(|group| group.name() == key)
            .ok_or_else(|| unknown_key(key, END_PATCH))?;
        // A group set to `null` removes the whole group from the end state,
        // which is the same removal one key deep.
        if body.is_null() {
            continue;
        }
        check_group_patch(body, group, END_PATCH, key)?;
    }
    Ok(())
}

/// The two refusals that are about this op rather than the vocabulary,
/// asked of a group and a key wherever they came from — a `patch`'s keys
/// and an `off` path go through the same two sentences. The third arm is
/// `off`'s alone: a cutout's presence is the clip's own (spec §11 CO-20),
/// so an end may not take it away; a `patch` naming `video.cutout` is
/// [`check_cutout_end`]'s.
pub(crate) fn not_a_target(group: &str, key: &str) -> Result<(), String> {
    match (group, key) {
        ("video", "motion") => Err("video.motion is not an animation target".to_string()),
        ("video", "hide_silent") => Err("video.hide_silent is not an animation target".to_string()),
        ("text", "words") => Err("text.words is not an animation target".to_string()),
        ("video", "cutout") => Err("video.cutout cannot be keyed off at an action's end; \
                                    set_video {cutout: null} removes it"
            .to_string()),
        _ => Ok(()),
    }
}

/// A `patch`'s `video.cutout` naming `subject` or `quality` — a `null`
/// included, `subject` asked first — refused by name (spec §11 CO-20): which
/// subject and which masks are the clip's own, and the evaluator restores
/// the base's over any end (`cutout_check.rs`'s `restore_base_cutout`).
/// `edge`, `feather` and `background` pass; anything that is not an object
/// is the walk's to judge.
pub(crate) fn check_cutout_end(patch: &Value) -> Result<(), String> {
    let Some(Value::Object(cutout)) = patch.get("video").and_then(|video| video.get("cutout"))
    else {
        return Ok(());
    };
    for key in ["subject", "quality"] {
        if cutout.contains_key(key) {
            return Err(format!("video.cutout.{key} is not an animation target"));
        }
    }
    Ok(())
}

/// The EQ's seven slots, the one group whose slot `off` may name (AU-88).
#[rustfmt::skip]
const EQ_SLOTS: [&str; 7] =
    ["high_pass", "low_shelf", "band_1", "band_2", "band_3", "high_shelf", "low_pass"];

/// One `off` path: `group.key`, or `audio.eq.<slot>` with its `slot`.
pub(crate) struct OffPath<'a> {
    group: &'a str,
    key: &'a str,
    slot: Option<&'a str>,
}

/// Reads `set_action_end`'s `off` list (spec §11 CI-14) into its paths,
/// refusing in this order: a path that is not `group.key` or
/// `audio.eq.<slot>` (AU-88; an unknown slot named against the seven), a
/// group an end patch may not name, `video.motion`, `text.words` and
/// `video.cutout` (spec §11 CO-20), a path
/// `patch` also names, and whatever the group's read says of a `null` there
/// — an unknown key, a REQUIRED key (`video.opacity`).

import AppKit

/// The inspector's foot (spec §11 CI-10): "Refused: " and the rule's own
/// sentence, VERBATIM, when the core refused a person's edit.
/// `ProjectDocument.applyEdit` has already beeped; this is the one thing a
/// person sees that an identity does not show them.
///
/// It lasts until the PROJECT changes — `clearIfStale` runs at the top of
/// every inspector refresh and clears it once `editedProject` is another
/// handle, which is an applied edit, an undo, a redo or a scope change — or
/// until it is clicked. A playhead or selection move keeps the same handle,
/// so it keeps the strip. Hidden, it is detached from the foot's stack, so
/// it takes no room.
final class InspectorRefusalStrip: NSView {
    private(set) var text: String?
    /// The handle the refusal was shown under. Weak: a handle nothing else
    /// holds is one the project has moved away from, and nil is not it.
    private weak var project: ReelProject?
    private let label = NSTextField(wrappingLabelWithString: "")
    /// Its width pinned to the foot's, made on a show: hidden, the strip is
    /// detached from the foot's stack, and a constraint made once in
    /// `loadView` need not survive that.
    private var spanning: NSLayoutConstraint?

    init() {
        super.init(frame: .zero)
        wantsLayer = true
        isHidden = true
        label.font = DS.sans(11)
        label.textColor = DS.textStrong
        label.isSelectable = false
        label.maximumNumberOfLines = 3
        label.cell?.truncatesLastVisibleLine = true
        label.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        label.translatesAutoresizingMaskIntoConstraints = false
        addSubview(label)
        NSLayoutConstraint.activate([
            label.topAnchor.constraint(equalTo: topAnchor, constant: 8),
            label.bottomAnchor.constraint(equalTo: bottomAnchor, constant: -8),
            label.leadingAnchor.constraint(
                equalTo: leadingAnchor, constant: InspectorMetrics.inset),
            label.trailingAnchor.constraint(
                equalTo: trailingAnchor, constant: -InspectorMetrics.inset),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorRefusalStrip does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    /// A wrapping label needs its width to know its height.
    override func layout() {
        super.layout()
        let width = max(bounds.width - 2 * InspectorMetrics.inset, 0)
        guard label.preferredMaxLayoutWidth != width else { return }
        label.preferredMaxLayoutWidth = width
        super.layout()
    }

    override func draw(_ dirtyRect: NSRect) {
        DS.hoverFill.setFill()
        bounds.fill()
        DS.border.setFill()
        NSRect(x: 0, y: 0, width: bounds.width, height: 1).fill()
    }

    func show(_ refusal: ReelRefusal, under project: ReelProject?) {
        let sentence = "Refused: " + refusal.reason
        text = sentence
        self.project = project
        label.stringValue = sentence
        toolTip = sentence
        isHidden = false
        needsDisplay = true
    }

    /// Clears once the project is not the handle the refusal was shown under.
    func clearIfStale(_ project: ReelProject?) {
        guard text != nil, project !== self.project else { return }
        clear()
    }

    func clear() {
        guard text != nil else { return }
        text = nil
        project = nil
        label.stringValue = ""
        toolTip = nil
        isHidden = true
    }

    override func mouseDown(with event: NSEvent) {
        clear()
    }

    /// Pins the strip to `container`'s width unless that pin is still active.
    func span(_ container: NSView) {
        guard spanning?.isActive != true, isDescendant(of: container) else { return }
        spanning = widthAnchor.constraint(equalTo: container.widthAnchor)
        spanning?.isActive = true
    }
}

extension InspectorViewController {
    /// The editor's forward of `projectDocumentDidRefuse`.
    func showRefusal(_ refusal: ReelRefusal) {
        guard isViewLoaded else { return }
        refusalStrip.show(refusal, under: document?.editedProject)
