29	impl Project {
30	    /// Scales every action's span with the clip, so an action keeps the
31	    /// same clip-relative FRACTION when the clip's length changes (spec §6,
32	    /// `set_speed`).
33	    ///
34	    /// Rounding can leave two adjacent actions touching by a tick; that is
35	    /// harmless, because evaluation orders actions by `(start, id)` and is
36	    /// defined for overlaps — only `add_action` refuses to create one.
37	    pub(crate) fn rescale_actions(&self, actions: &mut [Action], old: Ticks, new: Ticks) {
38	        if old <= 0 || new <= 0 || old == new {
39	            return;
40	        }
41	        let frame = self.frame();
42	        let factor = new as f64 / old as f64;
43	        for action in actions.iter_mut() {
44	            let (start, duration) = self.scaled_span(action, factor);
45	            // Clamped so the action still fits the clip and still has a
46	            // positive duration, which `validate` requires.
47	            action.start = start.clamp(0, new.saturating_sub(frame).max(0));
48	            action.duration = duration
49	                .max(frame)
50	                .min(new.saturating_sub(action.start))
51	                .max(1);
52	        }
53	    }
54	
55	    /// `action`'s start and duration × `factor`, each rounded then snapped
56	    /// to the grid. A product that is not finite keeps the old value. NOT
57	    /// clamped: `rescale_actions` clamps what it takes from here, and
58	    /// `scaled_profile` leaves a speed action where it lands (spec §11
59	    /// SR-19 (b)).
60	    pub(crate) fn scaled_span(&self, action: &Action, factor: f64) -> (Ticks, Ticks) {
61	        let scaled_start = (action.start as f64 * factor).round();
62	        let scaled_duration = (action.duration as f64 * factor).round();
63	        let start = if scaled_start.is_finite() {
64	            self.snapped(scaled_start as Ticks)
65	        } else {
66	            action.start
67	        };
68	        let duration = if scaled_duration.is_finite() {
69	            self.snapped(scaled_duration as Ticks)
70	        } else {
71	            action.duration
72	        };
73	        (start, duration)
74	    }
