76	    /// `clip` with its whole rate profile × `factor`, `duration` long (spec
77	    /// §11 SR-19 (a), (b)): `speed` and every action's numeric `end.speed`,
78	    /// each product clamped to `SPEED_MIN`–`SPEED_MAX` (no rate is
79	    /// rewritten when `factor` is 1). Every SPEED action's span scales by
80	    /// `duration / clip.duration`, snapped and NOT clamped into the clip, so
81	    /// one running past the end still does and S∞′(t·D′/D) = S∞(t); every
82	    /// other action is rescaled and clamped as `rescale_actions` does. The
83	    /// duration is then held through S∞ with the speed actions as they stand
84	    /// (D4-3's `duration_resnapped`), as `trim_end` leaves them; when the
85	    /// hold shortens the clip, the other actions are re-clamped into what is
86	    /// left, as `resnap_clip_times`' second pass does (`resnap_actions`).
87	    pub(crate) fn scaled_profile(&self, clip: &Clip, factor: f64, duration: Ticks) -> Clip {
88	        let mut scaled = clip.clone();
89	        if factor != 1.0 {
90	            scaled.speed = (clip.speed * factor).clamp(SPEED_MIN, SPEED_MAX);
91	        }
92	        let frame = self.frame();
93	        let span = duration as f64 / clip.duration as f64;
94	        for action in scaled.actions.iter_mut() {
95	            let Some(rate) = end_speed(action) else {
96	                self.rescale_actions(std::slice::from_mut(action), clip.duration, duration);
97	                continue;
98	            };
99	            if factor != 1.0 {
100	                if let Value::Object(end) = &mut action.end {
101	                    let product = (rate * factor).clamp(SPEED_MIN, SPEED_MAX);
102	                    end.insert("speed".to_string(), Value::from(product));
103	                }
104	            }
105	            let (start, length) = self.scaled_span(action, span);
106	            action.start = start.max(0);
107	            action.duration = length.max(frame).max(1);
108	        }
109	        scaled.duration = duration;
110	        scaled.duration = self.duration_resnapped(&scaled);
111	        if scaled.duration != duration {
112	            resnap_actions(self, &mut scaled);
113	        }
114	        scaled
115	    }
116	}
