155	            return to;
156	        }
157	        let end = clip_end(clip);
158	        let fits = |position: Ticks| {
159	            let mut trial = clip.clone();
160	            trial.source = source_advanced_through(clip, position.saturating_sub(clip.start));
161	            trial.start = position;
162	            trial.duration = end.saturating_sub(position);
163	            self.overrun(&trial).is_none()
