476	/// The evaluated state as an action-style patch object, so `split` can hand
477	/// the first half of a straddled action the state it must reach. A
478	/// graphic's evaluated props go in as `graphic.props` (G-34), which
479	/// [`narrow_to`] narrows to the props the action named, carrying its
480	/// `kinds` through untouched.
481	pub(crate) fn state_patch(evaluated: &Evaluated) -> Value {
482	    let mut out = serde_json::Map::new();
483	    // `video_json`: a tone key at exactly 0 at the cut must still be here,
484	    // or `narrow_to` puts back the action's END value (spec §11 GR-2).
485	    out.insert("video".to_string(), actions::video_json(&evaluated.video));
486	    out.insert("audio".to_string(), actions::to_json(&evaluated.audio));
487	    if let Some(text) = &evaluated.text {
488	        out.insert("text".to_string(), actions::to_json(text));
489	    }
490	    if let Some(graphic) = &evaluated.graphic {
491	        let mut props = serde_json::Map::new();
492	        props.insert("props".to_string(), Value::Object(graphic.props.clone()));
493	        out.insert("graphic".to_string(), Value::Object(props));
494	    }
495	    Value::Object(out)
496	}
497	
498	/// `state` narrowed to the keys `shape` mentions — the minimal patch with
499	/// the same reach as the original. Keeping the shape means a split action's
500	/// first half animates exactly the fields the whole action animated, rather
501	/// than pinning every property of the clip.
502	pub(crate) fn narrow_to(state: &Value, shape: &Value, depth: u32) -> Value {
503	    let (Value::Object(from), Value::Object(keys)) = (state, shape) else {
504	        return shape.clone();
505	    };
506	    if depth >= MAX_PATCH_DEPTH {
507	        return shape.clone();
508	    }
509	    let mut out = serde_json::Map::new();
510	    for (key, sub) in keys {
511	        match from.get(key) {
512	            Some(value) if value.is_object() && sub.is_object() => {
513	                out.insert(key.clone(), narrow_to(value, sub, depth + 1));
514	            }
515	            Some(value) => {
516	                out.insert(key.clone(), value.clone());
517	            }
518	            // A key the state does not have (an unknown patch key): carry
519	            // the original through untouched, exactly as evaluation would.
520	            None => {
521	                out.insert(key.clone(), sub.clone());
522	            }
523	        }
524	    }
525	    Value::Object(out)
526	}
