528	/// Cuts `clip_id` in two at project time `at`, in place. Returns false —
529	/// and changes nothing — when `at` is not strictly inside the clip, which
530	/// is the spec's refusal.
531	///
532	/// The second clip's BASE props are the evaluated state at the cut, so the
533	/// join is invisible; its actions are the ones that had not finished,
534	/// rebased to its own clip time. A graphic's `props` are the evaluated
535	/// ones, and a straddled action's first half ends at them (G-34).
536	pub(crate) fn split_clip(project: &mut Project, clip_id: u32, at: Ticks) -> bool {
537	    let Some(original) = project.clip(clip_id).cloned() else {
538	        return false;
539	    };
540	    let clip_t = at.saturating_sub(original.start);
541	    if clip_t <= 0 || clip_t >= original.duration {
542	        return false;
543	    }
544	    let state = project.evaluate_clip(&original, clip_t);
545	    let patch_source = state_patch(&state);
546	    // The ORIGINAL's map, read once: a ramped clip's halves meet at the
547	    // source it read by the cut (spec §11 SR-18 (e)). `None` for a
548	    // constant clip, which takes the one-rate path unchanged.
549	    let map = SpeedMap::of(&original);
550	    // Measured on the ORIGINAL, so a null `length` is `in` plus the WHOLE
551	    // duration, not the half either piece keeps.
552	    let pinned = effective_length(&original);
553	
554	    let mut second = original.clone();
555	    second.id = project.allocate_id();
556	    second.start = at;
557	    second.duration = clip_end(&original).saturating_sub(at);
558	    // The cut consumes `clip_t` of timeline, which is `clip_t * speed` of
559	    // source — round(S(cut)) on a ramped clip, whose second half starts at
560	    // the rate in force there; a still's frozen frame and the sourceless
561	    // kinds do not move, which is `source_advanced_through`'s own rule.
562	    second.source = source_advanced_through(&original, clip_t);
563	    if let Some(map) = &map {
564	        second.speed = map.rate_at(clip_t);
565	    }
566	    // A graphic's own timeline (road map 10's G-9): the second half starts
567	    // `clip_t` further into it, and BOTH halves keep the original's length,
568	    // so the join is invisible and neither half's outro moves — the first
569	    // half's `in + duration` would otherwise be only the head.
570	    second.graphic = graphic_advanced(state.graphic.as_ref(), clip_t);
571	    if let Some(graphic) = second.graphic.as_mut() {
572	        graphic.length = pinned;
573	    }
574	    // Presence of a group is a fact about the clip, so an audio-only clip
575	    // stays audio-only; only the values come from the evaluation.
576	    // The cursor's `smoothing` and `hide_idle` stay the original's BASE
577	    // values, never an end's (spec §11 CU-30).
578	    second.video = original
579	        .video
580	        .as_ref()
581	        .map(|_| with_base_cursor(state.video.clone(), original.video.as_ref()));
582	    second.audio = original.audio.map(|_| state.audio);
583	    second.text = state.text.clone();
584	    second.shape = original.shape.clone();
585	    // The transition covers the join with the PREVIOUS clip, which is still
586	    // the first half's business (spec §6).
587	    second.transition_in = None;
588	
589	    // A preset anchored to the clip's two ends, cut in two: the FIRST half
590	    // keeps the entrance and gives up the exit, the SECOND keeps the exit
591	    // and gives up the entrance (format version 8). Carrying both to both
592	    // halves — which is what a bare clone does, and what `text.animation`
593	    // had done since format version 5 — makes the first half leave at the
594	    // cut and the second arrive again there, so a join a viewer is not
595	    // supposed to see becomes the most visible thing in the shot. Neither
596	    // half's kept slot is rescaled: a preset is a duration, and the tent
597	    // rule (`motion.rs`) is what handles one now too long for the half it
