608	                    motion.out = None;
609	                } else {
610	                    motion.r#in = None;
611	                }
612	                if motion.is_empty() {
613	                    video.motion = None;
614	                }
615	            }
616	        }
617	    };
618	    motion_of(&mut second.video, false);
