1	//! The rate profile a rate edit scales: the factors a ramped clip's whole
2	//! profile may be scaled by, and the helpers that scale a clip's actions
3	//! and its profile with its length (spec §6 `set_speed`, §11 SR-19). A pure
4	//! move out of `edit_clip_timing.rs` (road map "creator-jobs" CU9a's toll),
5	//! shared by `set_speed`, `rate_stretch` and `retime_range`.
6	
7	use serde_json::Value;
8	
9	use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
10	use crate::frame_grid::resnap_actions;
11	use crate::model::{Action, Clip, Project};
12	use crate::speed_map::{end_speed, SpeedMap};
13	use crate::time::Ticks;
14	
15	/// The range of factors one rate edit may scale a RAMPED clip's whole
16	/// profile by: `(SPEED_MIN / r_min, SPEED_MAX / r_max)`, r over the base
17	/// and every action's `end_speed` (the rates `peak_rate` reads), so no rate
18	/// the clip names leaves `SPEED_MIN`–`SPEED_MAX` (spec §11 SR-19 (a)).
19	/// `None` when [`SpeedMap::of`] is, which is every constant clip.
20	pub(crate) fn profile_factors(clip: &Clip) -> Option<(f64, f64)> {
21	    SpeedMap::of(clip)?;
22	    let rates = std::iter::once(clip.speed).chain(clip.actions.iter().filter_map(end_speed));
23	    let (low, high) = rates.fold((f64::INFINITY, f64::NEG_INFINITY), |(lo, hi), r| {
24	        (lo.min(r), hi.max(r))
25	    });
26	    Some((SPEED_MIN / low, SPEED_MAX / high))
27	}
28	
29	impl Project {
30	    /// Scales every action's span with the clip, so an action keeps the
31	    /// same clip-relative FRACTION when the clip's length changes (spec §6,
32	    /// `set_speed`).
33	    ///
34	    /// Rounding can leave two adjacent actions touching by a tick; that is
35	    /// harmless, because evaluation orders actions by `(start, id)` and is
36	    /// defined for overlaps — only `add_action` refuses to create one.
37	    pub(crate) fn rescale_actions(&self, actions: &mut [Action], old: Ticks, new: Ticks) {
38	        if old <= 0 || new <= 0 || old == new {
39	            return;
40	        }
41	        let frame = self.frame();
42	        let factor = new as f64 / old as f64;
43	        for action in actions.iter_mut() {
44	            let (start, duration) = self.scaled_span(action, factor);
45	            // Clamped so the action still fits the clip and still has a
46	            // positive duration, which `validate` requires.
47	            action.start = start.clamp(0, new.saturating_sub(frame).max(0));
48	            action.duration = duration
49	                .max(frame)
50	                .min(new.saturating_sub(action.start))
51	                .max(1);
52	        }
53	    }
54	
55	    /// `action`'s start and duration × `factor`, each rounded then snapped
56	    /// to the grid. A product that is not finite keeps the old value. NOT
57	    /// clamped: `rescale_actions` clamps what it takes from here, and
58	    /// `scaled_profile` leaves a speed action where it lands (spec §11
59	    /// SR-19 (b)).
60	    pub(crate) fn scaled_span(&self, action: &Action, factor: f64) -> (Ticks, Ticks) {
61	        let scaled_start = (action.start as f64 * factor).round();
62	        let scaled_duration = (action.duration as f64 * factor).round();
63	        let start = if scaled_start.is_finite() {
64	            self.snapped(scaled_start as Ticks)
65	        } else {
66	            action.start
67	        };
68	        let duration = if scaled_duration.is_finite() {
69	            self.snapped(scaled_duration as Ticks)
70	        } else {
71	            action.duration
72	        };
73	        (start, duration)
74	    }
75	
76	    /// `clip` with its whole rate profile × `factor`, `duration` long (spec
77	    /// §11 SR-19 (a), (b)): `speed` and every action's numeric `end.speed`,
78	    /// each product clamped to `SPEED_MIN`–`SPEED_MAX` (no rate is
79	    /// rewritten when `factor` is 1). Every SPEED action's span scales by
80	    /// `duration / clip.duration`, snapped and NOT clamped into the clip, so
81	    /// one running past the end still does and S∞′(t·D′/D) = S∞(t); every
82	    /// other action is rescaled and clamped as `rescale_actions` does. The
83	    /// duration is then held through S∞ with the speed actions as they stand
84	    /// (D4-3's `duration_resnapped`), as `trim_end` leaves them; when the
85	    /// hold shortens the clip, the other actions are re-clamped into what is
86	    /// left, as `resnap_clip_times`' second pass does (`resnap_actions`).
87	    pub(crate) fn scaled_profile(&self, clip: &Clip, factor: f64, duration: Ticks) -> Clip {
88	        let mut scaled = clip.clone();
89	        if factor != 1.0 {
90	            scaled.speed = (clip.speed * factor).clamp(SPEED_MIN, SPEED_MAX);
91	        }
92	        let frame = self.frame();
93	        let span = duration as f64 / clip.duration as f64;
94	        for action in scaled.actions.iter_mut() {
95	            let Some(rate) = end_speed(action) else {
96	                self.rescale_actions(std::slice::from_mut(action), clip.duration, duration);
97	                continue;
98	            };
99	            if factor != 1.0 {
100	                if let Value::Object(end) = &mut action.end {
101	                    let product = (rate * factor).clamp(SPEED_MIN, SPEED_MAX);
102	                    end.insert("speed".to_string(), Value::from(product));
103	                }
104	            }
105	            let (start, length) = self.scaled_span(action, span);
106	            action.start = start.max(0);
107	            action.duration = length.max(frame).max(1);
108	        }
109	        scaled.duration = duration;
110	        scaled.duration = self.duration_resnapped(&scaled);
111	        if scaled.duration != duration {
112	            resnap_actions(self, &mut scaled);
113	        }
114	        scaled
115	    }
116	}
117	/// A RAMPED clip's TIMELINE ticks from `source_in` to the end of `media`,
118	/// read through S∞ ([`time_for_source`], spec §11 SR-18 (a)); `None` for a
119	/// constant clip, which takes [`available_on_timeline`].
120	fn ramped_available_on_timeline(clip: &Clip, media: &Media, source_in: Ticks) -> Option<Ticks> {
121	    time_for_source(clip, media.duration.saturating_sub(source_in).max(0))
122	}
123	
124	impl Project {
125	    /// A media clip's `in` and its file's duration, or `None` for any other
126	    /// source and an unknown media.
127	    pub(crate) fn window_of(&self, clip: &Clip) -> Option<(Ticks, Ticks)> {
128	        let Source::Media { media, r#in, .. } = &clip.source else {
129	            return None;
130	        };
131	        Some((*r#in, self.media(*media)?.duration))
132	    }
133	
134	    /// How many ticks past the end of its media `clip` reads, when it does.
135	    pub(crate) fn overrun(&self, clip: &Clip) -> Option<Ticks> {
136	        let (source_in, file) = self.window_of(clip)?;
137	        let over = source_in
138	            .saturating_add(self.content_length_in_source(clip))
139	            .saturating_sub(file);
140	        (over > 0).then_some(over)
141	    }
142	
143	    /// A front-edge TIMELINE position for `clip` asked to start at `to`
144	    /// (spec §11 SR-18 (c)). `to` itself when the clip is constant, or when
145	    /// its trial — the source through [`source_advanced_through`], start
146	    /// `to`, its end kept, its actions unchanged — does not read past its
147	    /// file. Otherwise a fitting frame between `to` and `clip.start`, found
148	    /// by bisection on the frame grid, the start taken as fitting (the clip
149	    /// as it stands): a frame that fits beside one nearer `to` that does
150	    /// not, or `clip.start`. Because the fit is not monotone in the edge,
151	    /// that frame is not necessarily the fitting frame nearest `to`. A
152	    /// clamp because a gesture never refuses.
153	    pub(crate) fn front_edge_held(&self, clip: &Clip, to: Ticks) -> Ticks {
154	        if SpeedMap::of(clip).is_none() {
155	            return to;
156	        }
157	        let end = clip_end(clip);
158	        let fits = |position: Ticks| {
159	            let mut trial = clip.clone();
160	            trial.source = source_advanced_through(clip, position.saturating_sub(clip.start));
161	            trial.start = position;
162	            trial.duration = end.saturating_sub(position);
163	            self.overrun(&trial).is_none()
164	        };
165	        if fits(to) {
166	            return to;
167	        }
168	        let fps = self.canvas.fps;
169	        // Whole grid frames from `to` to the start, and the direction to
170	        // step them in: back toward an earlier start, forward toward a later.
171	        let (frames, step) = if to > clip.start {
172	            (frames_between(clip.start, to, fps), 1)
173	        } else {
174	            (frames_between(to, clip.start, fps), -1)
175	        };
176	        let at = |k: i64| frames_back(to, k.saturating_mul(step), fps);
177	        // `lo` does not fit; `hi` does, `frames + 1` standing for the start.
178	        let (mut lo, mut hi) = (0_i64, frames.max(0).saturating_add(1));
179	        while hi - lo > 1 {
180	            let mid = lo + (hi - lo) / 2;
181	            if fits(at(mid)) {
182	                hi = mid;
183	            } else {
184	                lo = mid;
185	            }
186	        }
187	        if hi > frames.max(0) {
188	            clip.start
189	        } else {
190	            at(hi)
191	        }
192	    }
193	
194	    /// The source material one clip shows, in SOURCE ticks: its timeline
195	    /// length times its speed. The same quantity `evaluate::segment_of`
196	    /// inserts into the composition — it reads this function, so a speed
197	    /// edit here and the segment there cannot disagree (spec §11, D4-1).
198	    ///
199	    /// The middle of the three measurements:
200	    /// [`Project::source_head_on_timeline`] is what lies before the window,
201	    /// this is the window, and [`Project::source_length_on_timeline`] is
202	    /// what a window starting at `in` could still grow to.
203	    pub fn content_length_in_source(&self, clip: &Clip) -> Ticks {
204	        // A RAMPED clip reads S(duration), the integral of its rate (spec
205	        // §11 SR-10); a constant clip, every other source among them, is
206	        // the one product below.
207	        if let Some(map) = SpeedMap::of(clip) {
208	            return (map.source_at(clip.duration).round() as Ticks).max(1);
209	        }
210	        let scaled = clip.duration as f64 * clip.speed;
211	        // The cast saturates rather than wrapping, so an absurd speed
212	        // cannot produce a negative length; a degenerate one falls back to
213	        // 1:1.
214	        if scaled.is_finite() && scaled >= 1.0 {
215	            scaled.round() as Ticks
216	        } else {
217	            clip.duration.max(1)
218	        }
219	    }
220	
221	    /// How much TIMELINE time lies before a clip's first frame — how far
222	    /// its front edge could be dragged left before the media runs out.
223	    /// `in` ticks of source lie in front, which is `in / speed` ticks of
224	    /// timeline at this clip's rate.
225	    ///
226	    /// `Unbounded` for a source with no window: a still, an image, text, a
227	    /// shape and a nest may begin anywhere. A degenerate speed is
228	    /// `Unmeasured` — the window exists, it just cannot be measured — which
229	    /// the two callers that clamp a front edge read as EMPTY.
230	    pub fn source_head_on_timeline(&self, clip: &Clip) -> SourceBound {
231	        let Source::Media { r#in, .. } = clip.source else {
232	            return SourceBound::Unbounded;
233	        };
234	        if !(clip.speed.is_finite() && clip.speed > 0.0) {
235	            return SourceBound::Unmeasured;
236	        }
237	        let head = (r#in.max(0) as f64 / clip.speed).floor();
238	        SourceBound::Timeline(if head.is_finite() { head as Ticks } else { 0 })
239	    }
240	
241	    /// The longest TIMELINE duration `clip` could have: the media's
242	    /// remaining source length from its in point, divided by `speed` (at 2x
243	    /// a 10 s remainder fills 5 s of timeline). Floored, so a clip can
244	    /// never outrun its source by a partial frame.
245	    ///
246	    /// `Unbounded` for a source with no source bound — `still`, `image`,
247	    /// `text`, `shape` and `nest` may have ANY duration. `Unmeasured` for an
248	    /// unknown media or a speed that is not a positive finite number: both
249	    /// were one `None` before, and they are still read the same way by every
250	    /// caller, but a caller now says which reading it takes.
251	    pub fn source_length_on_timeline(&self, clip: &Clip) -> SourceBound {
252	        let (media_id, source_in) = match &clip.source {
253	            Source::Media { media, r#in, .. } => (*media, *r#in),
254	            _ => return SourceBound::Unbounded,
255	        };
256	        let Some(media) = self.media(media_id) else {
257	            return SourceBound::Unmeasured;
258	        };
259	        if !(clip.speed.is_finite() && clip.speed > 0.0) {
260	            return SourceBound::Unmeasured;
261	        }
262	        // A RAMPED clip reads on through S∞ (spec §11 SR-18 (a)).
263	        if let Some(available) = ramped_available_on_timeline(clip, media, source_in) {
264	            return SourceBound::Timeline(available);
265	        }
266	        SourceBound::Timeline(available_on_timeline(media, source_in, clip.speed))
267	    }
268	
269	    /// THE bound, from the pieces: the longest TIMELINE duration a window
270	    /// of `media` from `source_in` at `speed`, placed at `start`, could
271	    /// have and still END on the frame grid inside the file.
272	    ///
273	    /// The division is floored and lands anywhere, so a length taken
274	    /// straight from it is not on the grid; snapped to the NEAREST frame it
275	    /// rounds UP past the end of the file whenever the last frame is more
276	    /// than half a frame short, which is exactly the defect spec §11's #22
277	    /// closed. Down, `in + duration × speed ≤ media.duration` holds by
278	    /// construction and the plan hands the clip a segment that plays at
279	    /// exactly the clip's speed.
280	    ///
281	    /// **`start` is a parameter because the two readings differ** (spec
282	    /// §11, D4-2). At `start = 0` this is `snapped_down(available)`, a grid
283	    /// LENGTH — what a site that writes a DURATION wants. At
284	    /// `start = clip.start` the clip's END is what lands on the grid, which
285	    /// is not the same number when the start is off the grid, nor at a rate
286	    /// whose frame is not a whole tick count. `Unmeasured` for a speed that
287	    /// is not a positive finite number: the window is there, the arithmetic
288	    /// is not.
289	    pub(crate) fn longest_duration_on_grid_of(
290	        &self,
291	        start: Ticks,
292	        media: &Media,
293	        source_in: Ticks,
294	        speed: f64,
295	    ) -> SourceBound {
296	        if !(speed.is_finite() && speed > 0.0) {
297	            return SourceBound::Unmeasured;
298	        }
299	        let available = available_on_timeline(media, source_in, speed);
300	        let end = self.snapped_down(start.saturating_add(available));
301	        SourceBound::Timeline(end.saturating_sub(start).max(0))
302	    }
303	
304	    /// THE bound a media clip's DURATION is held to:
305	    /// [`Project::longest_duration_on_grid_of`] measured at start 0, which
306	    /// is the whole window snapped DOWN to the canvas frame grid.
307	    ///
308	    /// `Unbounded` for a source with no window and `Unmeasured` for an
309	    /// unknown media, exactly as [`Project::source_length_on_timeline`]
310	    /// answers them.
311	    pub fn longest_duration_on_grid(&self, clip: &Clip) -> SourceBound {
312	        let (media_id, source_in) = match &clip.source {
313	            Source::Media { media, r#in, .. } => (*media, *r#in),
314	            _ => return SourceBound::Unbounded,
315	        };
316	        let Some(media) = self.media(media_id) else {
317	            return SourceBound::Unmeasured;
318	        };
319	        // A RAMPED clip's window through S∞ (spec §11 SR-18 (a)), snapped
320	        // down from tick 0 as the constant reading is.
321	        if let Some(available) = ramped_available_on_timeline(clip, media, source_in) {
322	            return SourceBound::Timeline(self.snapped_down(available).max(0));
323	        }
324	        self.longest_duration_on_grid_of(0, media, source_in, clip.speed)
325	    }
326	
327	    /// The latest timeline POSITION a media clip's end edge may reach — its
328	    /// own start plus the bound measured THERE, so the end lands on the
329	    /// frame grid and inside the file.
330	    ///
331	    /// `None` means apply no clamp, and it is the `or_unbounded` reading
332	    /// both callers (`trim_end`, `roll`'s tail) already took: a source with
333	    /// no window cannot be argued with, and neither can one whose
334	    /// arithmetic is unmeasurable (spec §11, D4-2).
335	    pub(crate) fn latest_end_on_grid(&self, clip: &Clip) -> Option<Ticks> {
336	        let (media_id, source_in) = match &clip.source {
337	            Source::Media { media, r#in, .. } => (*media, *r#in),
338	            _ => return None,
339	        };
340	        let media = self.media(media_id)?;
341	        // A RAMPED clip's window through S∞ (spec §11 SR-18 (a)), its END
342	        // snapped down from the clip's own start as the constant reading is.
343	        if let Some(available) = ramped_available_on_timeline(clip, media, source_in) {
344	            let end = self.snapped_down(clip.start.saturating_add(available));
345	            return Some(end.max(clip.start));
346	        }
347	        let bound = self
348	            .longest_duration_on_grid_of(clip.start, media, source_in, clip.speed)
349	            .or_unbounded()?;
350	        Some(clip.start.saturating_add(bound))
351	    }
352	
353	    /// The earliest timeline POSITION a media clip's front edge may reach:
354	    /// its start less its head, snapped UP so the edge lands on a frame
355	    /// that is really inside the source (spec §11, D4-5).
356	    ///
357	    /// A timeline position and therefore NOT a [`SourceBound`]:
358	    /// [`SourceBound::or_empty`]'s `Some(0)` is a LENGTH, and a caller
359	    /// reading it as a position would take it for "back to tick 0". `None`
360	    /// is no window and no clamp; an `Unmeasured` head is EMPTY, which is
361	    /// what all three callers read it as. The answer may be NEGATIVE — a
362	    /// clip may start before tick 0 in the arithmetic if not in the model —
363	    /// so each caller keeps its own `.max(0)`.
364	    pub(crate) fn earliest_start_on_grid(&self, clip: &Clip) -> Option<Ticks> {
365	        let head = self.source_head_on_timeline(clip).or_empty()?;
366	        Some(self.snapped_up(clip.start.saturating_sub(head)))
367	    }
368	
369	    /// What every RE-SNAP of a media clip's duration writes: the stored
370	    /// duration on this document's grid, at least one frame, and never
371	    /// longer than the window the file still holds (spec §11, D4-4).
372	    ///
373	    /// `set_canvas`'s re-snap, `paste`'s clip loop, `paste`'s nest absorb,
374	    /// `unnest` and `relink_media`'s hold (#63) all write this one number.
375	    /// The one-frame floor is applied LAST and so wins over the bound: a
376	    /// media shorter than a canvas frame still leaves a clip a frame long,
377	    /// which is one of the cases `evaluate.rs`'s last-line clamp stays for.
378	    ///
379	    /// Preconditions: the clip's media resolves in `self` (an unmeasurable
380	    /// window is simply not clamped), and a degenerate `speed` has already
381	    /// been set to 1.0 where the caller does that.
382	    pub(crate) fn duration_resnapped(&self, clip: &Clip) -> Ticks {
383	        let frame = self.frame();
384	        let snapped = self.snapped(clip.duration).max(frame);
385	        match self.longest_duration_on_grid(clip).or_unbounded() {
386	            Some(bound) => snapped.min(bound).max(frame),
387	            None => snapped,
388	        }
389	    }
390	
391	    /// What `set_speed` writes: the clip's own content length played at
392	    /// `rate`, snapped to the NEAREST frame and then held to the bound
393	    /// measured AT THAT RATE (spec §11, D4-3).
394	    ///
395	    /// The content length is read off `clip` AS GIVEN — at its OLD speed,
396	    /// since that is the window it is showing — but the bound is measured
397	    /// on a copy running at `rate`, because that is the speed the segment
398	    /// will play at and the one the invariant has to hold for. A quotient
399	    /// that is not finite leaves the duration alone. `rate` arrives already
400	    /// clamped to `SPEED_MIN`–`SPEED_MAX`.
401	    pub(crate) fn duration_at_speed(&self, clip: &Clip, rate: f64) -> Ticks {
402	        let scaled = self.content_length_in_source(clip) as f64 / rate;
403	        if !scaled.is_finite() {
404	            return clip.duration;
405	        }
406	        let mut at_rate = clip.clone();
407	        at_rate.speed = rate;
408	        at_rate.duration = scaled.round() as Ticks;
409	        self.duration_resnapped(&at_rate)
410	    }
411	
412	    /// The last SOURCE tick a clip's window could START at and still fit
413	    /// inside `media`: what is left over when the window is pushed against
414	    /// the tail of the file.
415	    ///
416	    /// A window longer than its own media — which a speed edit can leave
417	    /// behind — has no room at all rather than negative room, which is the
418	    /// floor at 0.
419	    pub(crate) fn last_in_point(&self, clip: &Clip, media: &Media) -> Ticks {
420	        media
421	            .duration
422	            .max(0)
423	            .saturating_sub(self.content_length_in_source(clip))
424	            .max(0)
425	    }
426	
427	    /// The last SOURCE tick a STILL could hold, one canvas frame short of
428	    /// the end of `media`.
429	    ///
430	    /// A still is one instant, not a window, so all it needs is a margin
431	    /// from the end. How long a still's source segment really is — one
432	    /// frame at the MEDIA's rate — is `evaluate.rs`'s business, and the
433	    /// canvas frame is a good enough margin here.
434	    pub(crate) fn last_still_time(&self, media: &Media) -> Ticks {
435	        media.duration.saturating_sub(self.frame()).max(0)
436	    }
437	}
438	//! Cutting one clip in two — `split_clip` and the two helpers only it has
439	//! ever needed, `state_patch` and `narrow_to`.
440	//!
441	//! Cut out of `edit_clip.rs` in road map 5's E2, which owed it a rule about
442	//! `video.motion` and found a 1171-line file, and cut HERE because a split
443	//! is not a placement: every other op in `edit_clip.rs` decides where a
444	//! clip sits or what it is made of, while this one has to decide what the
445	//! SECOND clip inherits — its base props from the evaluation at the cut, so
446	//! the join is invisible; the actions that had not finished, rebased to its
447	//! own clip time, with a straddled one narrowed to the keys it animated;
448	//! and, since E2, the halves of a preset anchored to the clip's two ends.
449	//! The cursor's `smoothing` and `hide_idle` are the one exception to "the
450	//! evaluation at the cut": the second half keeps the original's base values
451	//! (spec §11 CU-30).
452	//! That inheritance question is the whole of this module and appears
453	//! nowhere else in the crate.
454	//!
455	//! Every splitter in the crate routes here — `split_clips`,
456	//! `split_under_playhead`, `clear_range` (so `ripple_delete_range(s)` and
457	//! `lift_range`), `insert_clip`, `overwrite_clip`, `freeze_frame` and
458	//! `keep_range` — so a rule stated once is a rule they all obey. It is a
459	//! free function taking `&mut Project` rather than a `Project` method for
460	//! the reason it always was: it is called mid-edit on a clone the caller is
461	//! still assembling, after `finish` would be too late and before it has
462	//! anything to hand back.
463	
464	use serde_json::Value;
465	
466	use crate::actions::{self, Evaluated, MAX_PATCH_DEPTH};
467	use crate::cursor_props::with_base_cursor;
468	use crate::edit_clip::clip_end;
469	use crate::model::{Action, Curve, Project, VideoProps};
470	use crate::model_words::{rebase_words, token_count};
471	use crate::recipe_graphic::{effective_length, graphic_advanced};
472	use crate::source_window::source_advanced_through;
473	use crate::speed_map::{end_speed, SpeedMap};
474	use crate::time::Ticks;
475	
476	/// The evaluated state as an action-style patch object, so `split` can hand
477	/// the first half of a straddled action the state it must reach. A
478	/// graphic's evaluated props go in as `graphic.props` (G-34), which
479	/// [`narrow_to`] narrows to the props the action named, carrying its
480	/// `kinds` through untouched.
481	pub(crate) fn state_patch(evaluated: &Evaluated) -> Value {
482	    let mut out = serde_json::Map::new();
483	    // `video_json`: a tone key at exactly 0 at the cut must still be here,
484	    // or `narrow_to` puts back the action's END value (spec §11 GR-2).
485	    out.insert("video".to_string(), actions::video_json(&evaluated.video));
486	    out.insert("audio".to_string(), actions::to_json(&evaluated.audio));
487	    if let Some(text) = &evaluated.text {
488	        out.insert("text".to_string(), actions::to_json(text));
489	    }
490	    if let Some(graphic) = &evaluated.graphic {
491	        let mut props = serde_json::Map::new();
492	        props.insert("props".to_string(), Value::Object(graphic.props.clone()));
493	        out.insert("graphic".to_string(), Value::Object(props));
494	    }
495	    Value::Object(out)
496	}
497	
498	/// `state` narrowed to the keys `shape` mentions — the minimal patch with
499	/// the same reach as the original. Keeping the shape means a split action's
500	/// first half animates exactly the fields the whole action animated, rather
501	/// than pinning every property of the clip.
502	pub(crate) fn narrow_to(state: &Value, shape: &Value, depth: u32) -> Value {
503	    let (Value::Object(from), Value::Object(keys)) = (state, shape) else {
504	        return shape.clone();
505	    };
506	    if depth >= MAX_PATCH_DEPTH {
507	        return shape.clone();
508	    }
509	    let mut out = serde_json::Map::new();
510	    for (key, sub) in keys {
511	        match from.get(key) {
512	            Some(value) if value.is_object() && sub.is_object() => {
513	                out.insert(key.clone(), narrow_to(value, sub, depth + 1));
514	            }
515	            Some(value) => {
516	                out.insert(key.clone(), value.clone());
517	            }
518	            // A key the state does not have (an unknown patch key): carry
519	            // the original through untouched, exactly as evaluation would.
520	            None => {
521	                out.insert(key.clone(), sub.clone());
522	            }
523	        }
524	    }
525	    Value::Object(out)
526	}
