    }

    /// One `set_speed` duration arm per clip, so a multi-clip Fit is one undo
    /// step.
    static func fitOps(_ clips: [UInt32], duration: Ticks) -> [ReelOp] {
        clips.map { .setSpeed(clip: $0, duration: duration) }
    }
