/// A constant time-scaled Keep pitch off segment's ramp object (spec §11
/// SR-28): keep pitch off, no glide, the map `[[0, source_in], [duration,
/// source_in + source_duration]]`, flagged `constant`.
pub(crate) fn constant_ramp_audio(
    source_in: Ticks,
