        if name == "Captions" { return true }
        guard name.hasPrefix("Captions ") else { return false }
        let suffix = name.dropFirst("Captions ".count)
        return !suffix.isEmpty && suffix.allSatisfy { $0.isASCII && $0.isNumber }
